"""Tool registry for the ComfyUI SUPER DUPER Agent.

Each tool module exports:
  TOOLS: list[dict]    -- Anthropic tool schemas
  handle(name, input)  -- Execute a tool call, return result string

Intelligence layers (53 tools) + Brain layer (27 tools) = 80 tools total.
Brain tools are lazily imported to avoid circular dependencies
(brain modules import _util from this package).
"""

import logging
import threading

from . import comfy_api, comfy_inspect, workflow_parse, workflow_patch, comfy_execute, comfy_discover, session_tools, workflow_templates, civitai_api, model_compat, verify_execution, github_releases, pipeline, image_metadata, node_replacement

log = logging.getLogger(__name__)

_MODULES = (comfy_api, comfy_inspect, workflow_parse, workflow_patch, comfy_execute, comfy_discover, session_tools, workflow_templates, civitai_api, model_compat, verify_execution, github_releases, pipeline, image_metadata, node_replacement)

# Intelligence layer tool schemas
_LAYER_TOOLS: list[dict] = []
for _mod in _MODULES:
    _LAYER_TOOLS.extend(_mod.TOOLS)

# Map tool name -> handler module (intelligence layers)
_HANDLERS = {}
for _mod in _MODULES:
    for _tool in _mod.TOOLS:
        _HANDLERS[_tool["name"]] = _mod

# Brain tools are loaded lazily to break the circular import
_brain_loaded = False
_brain_lock = threading.Lock()
_BRAIN_TOOL_NAMES: set[str] = set()


def _ensure_brain():
    """Lazily load brain layer tools (thread-safe)."""
    global _brain_loaded, _BRAIN_TOOL_NAMES
    if _brain_loaded:
        return
    with _brain_lock:
        if _brain_loaded:  # double-check after acquiring lock
            return
        from ..brain import ALL_BRAIN_TOOLS
        _BRAIN_TOOL_NAMES.update(t["name"] for t in ALL_BRAIN_TOOLS)
        _brain_loaded = True


def _get_all_tools() -> list[dict]:
    """Get all tool schemas (intelligence + brain layers)."""
    _ensure_brain()
    from ..brain import ALL_BRAIN_TOOLS
    return _LAYER_TOOLS + list(ALL_BRAIN_TOOLS)


# Public API — ALL_TOOLS is a property-like accessor
class _ToolList(list):
    """Lazy tool list that includes brain tools on first access."""
    _initialized = False

    def _init_once(self):
        if not self._initialized:
            self._initialized = True
            self.extend(_LAYER_TOOLS)
            try:
                from ..brain import ALL_BRAIN_TOOLS
                self.extend(ALL_BRAIN_TOOLS)
            except ImportError:
                log.warning("Brain layer not available")

    def __iter__(self):
        self._init_once()
        return super().__iter__()

    def __len__(self):
        self._init_once()
        return super().__len__()

    def __getitem__(self, idx):
        self._init_once()
        return super().__getitem__(idx)


ALL_TOOLS = _ToolList()


def handle(
    name: str,
    tool_input: dict,
    *,
    session_id: str | None = None,
    progress: "ProgressCallback | None" = None,
) -> str:
    """Dispatch a tool call to the right handler.

    Args:
        name: Tool name to dispatch.
        tool_input: Tool arguments dict.
        session_id: Optional session ID for workflow state isolation.
                    Currently unused (default session), but enables future
                    multi-session MCP usage.
        progress: Optional progress reporter for long-running tools.
                  Passed through to handlers that support it.
    """
    from ..progress import ProgressCallback  # noqa: F811 (type only)

    # Check brain tools (lazy loaded)
    _ensure_brain()
    if name in _BRAIN_TOOL_NAMES:
        from ..brain import handle as handle_brain
        try:
            return handle_brain(name, tool_input)
        except Exception as e:
            log.error("Unhandled error in brain tool %s", name, exc_info=True)
            from ..errors import error_json
            return error_json(
                f"Something went wrong with {name}.",
                hint="Check the logs or try again.",
            )

    # Intelligence layer tools
    mod = _HANDLERS.get(name)
    if mod is None:
        log.warning("Unknown tool called: %s", name)
        return f"Unknown tool: {name}"
    try:
        # Forward progress to modules that accept it
        if mod is comfy_execute:
            return mod.handle(name, tool_input, progress=progress)
        return mod.handle(name, tool_input)
    except Exception as e:
        log.error("Unhandled error in tool %s", name, exc_info=True)
        from ..errors import error_json
        return error_json(
            f"Something went wrong with {name}.",
            hint="Check the logs or try again.",
        )

"""ComfyUI HTTP API tools.

Wraps the ComfyUI REST API as Agent SDK tools so the agent can
query the running ComfyUI instance for node info, system stats,
queue status, and execution history.
"""

import httpx

from ..circuit_breaker import COMFYUI_BREAKER
from ..config import COMFYUI_URL
from ._util import to_json

# ---------------------------------------------------------------------------
# Tool schemas (Anthropic tool-use format)
# ---------------------------------------------------------------------------

TOOLS: list[dict] = [
    {
        "name": "is_comfyui_running",
        "description": (
            "Check if ComfyUI is running and reachable. "
            "Call this first before using other ComfyUI tools."
        ),
        "input_schema": {
            "type": "object",
            "properties": {},
            "required": [],
        },
    },
    {
        "name": "get_all_nodes",
        "description": (
            "Get registered node types in ComfyUI via GET /object_info. "
            "Use format='names_only' (just class_type names) or "
            "'summary' (name+category) to control response size. "
            "Use 'full' for complete input/output schemas. "
            "Prefer get_node_info for a specific node."
        ),
        "input_schema": {
            "type": "object",
            "properties": {
                "category_filter": {
                    "type": "string",
                    "description": (
                        "Optional substring to filter nodes by category "
                        "(e.g. 'sampling', 'loaders', 'image'). "
                        "Case-insensitive."
                    ),
                },
                "name_filter": {
                    "type": "string",
                    "description": (
                        "Optional substring to filter nodes by class_type name "
                        "(e.g. 'KSampler', 'ControlNet'). Case-insensitive."
                    ),
                },
                "format": {
                    "type": "string",
                    "enum": ["names_only", "summary", "full"],
                    "description": (
                        "Response format. 'names_only': just class_type names (smallest). "
                        "'summary': name + category + display_name (default). "
                        "'full': includes input types and output types."
                    ),
                },
            },
            "required": [],
        },
    },
    {
        "name": "get_node_info",
        "description": (
            "Get detailed info for a specific ComfyUI node type: "
            "its required/optional inputs with types and defaults, "
            "output types, category, and description. "
            "Use the exact class_type name (e.g. 'KSampler', 'CLIPTextEncode')."
        ),
        "input_schema": {
            "type": "object",
            "properties": {
                "node_type": {
                    "type": "string",
                    "description": "Exact class_type name of the node.",
                },
            },
            "required": ["node_type"],
        },
    },
    {
        "name": "get_system_stats",
        "description": (
            "Get ComfyUI system stats: GPU info, VRAM usage, "
            "Python version, and currently loaded models."
        ),
        "input_schema": {
            "type": "object",
            "properties": {},
            "required": [],
        },
    },
    {
        "name": "get_queue_status",
        "description": (
            "Get the current ComfyUI queue: running prompts and pending items."
        ),
        "input_schema": {
            "type": "object",
            "properties": {},
            "required": [],
        },
    },
    {
        "name": "get_history",
        "description": (
            "Get execution history from ComfyUI. Optionally filter by prompt_id. "
            "Returns outputs (images, videos) and execution status."
        ),
        "input_schema": {
            "type": "object",
            "properties": {
                "prompt_id": {
                    "type": "string",
                    "description": "Specific prompt ID to look up. Omit for recent history.",
                },
                "max_items": {
                    "type": "integer",
                    "description": "Max number of history items to return (default 5).",
                },
            },
            "required": [],
        },
    },
]

# ---------------------------------------------------------------------------
# HTTP helpers
# ---------------------------------------------------------------------------

_TIMEOUT = 15.0


def _get(path: str, timeout: float = _TIMEOUT) -> dict:
    """GET request to ComfyUI, returns parsed JSON.

    Raises httpx.ConnectError or httpx.HTTPStatusError on failure.
    Circuit breaker tracks failures and fast-fails when ComfyUI is down.
    """
    breaker = COMFYUI_BREAKER()
    if not breaker.allow_request():
        raise httpx.ConnectError(
            f"Circuit breaker open — ComfyUI at {COMFYUI_URL} has been unreachable. "
            f"Will retry in {breaker.recovery_timeout:.0f}s."
        )
    try:
        with httpx.Client() as client:
            resp = client.get(f"{COMFYUI_URL}{path}", timeout=timeout)
            resp.raise_for_status()
            breaker.record_success()
            return resp.json()
    except (httpx.ConnectError, httpx.TimeoutException) as e:
        breaker.record_failure()
        raise httpx.ConnectError(str(e)) from e


# ---------------------------------------------------------------------------
# Handlers
# ---------------------------------------------------------------------------

def _handle_is_running() -> str:
    try:
        stats = _get("/system_stats", timeout=5.0)
        devices = stats.get("devices", [])
        gpu = devices[0].get("name", "unknown") if devices else "no GPU detected"
        py_ver = stats.get("system", {}).get("python_version", "unknown")
        return to_json({
            "running": True,
            "url": COMFYUI_URL,
            "gpu": gpu,
            "python": py_ver,
        })
    except Exception as e:
        return to_json({
            "running": False,
            "url": COMFYUI_URL,
            "error": str(e),
        })


def _handle_get_all_nodes(tool_input: dict) -> str:
    cat_filter = (tool_input.get("category_filter") or "").lower()
    name_filter = (tool_input.get("name_filter") or "").lower()
    fmt = tool_input.get("format", "summary")

    all_info = _get("/object_info", timeout=30.0)

    # Apply filters
    filtered_names = []
    for name in sorted(all_info.keys()):
        info = all_info[name]
        cat = (info.get("category") or "").lower()
        if cat_filter and cat_filter not in cat:
            continue
        if name_filter and name_filter not in name.lower():
            continue
        filtered_names.append(name)

    # Format output based on requested detail level
    if fmt == "names_only":
        return to_json({
            "count": len(filtered_names),
            "nodes": filtered_names,
        })

    if fmt == "full":
        nodes = {}
        for name in filtered_names:
            info = all_info[name]
            nodes[name] = {
                "category": info.get("category", ""),
                "display_name": info.get("display_name", name),
                "description": info.get("description", ""),
                "input_types": sorted((info.get("input", {}).get("required", {})).keys()),
                "output_types": info.get("output", []),
            }
        return to_json({"count": len(nodes), "nodes": nodes})

    # Default: summary (name + category + display_name)
    nodes = {}
    for name in filtered_names:
        info = all_info[name]
        nodes[name] = {
            "category": info.get("category", ""),
            "display_name": info.get("display_name", name),
        }
    return to_json({
        "count": len(nodes),
        "nodes": nodes,
        "hint": "Use format='names_only' for smaller response, or get_node_info for details on a specific node.",
    })


def _handle_get_node_info(tool_input: dict) -> str:
    node_type = tool_input["node_type"]
    all_info = _get(f"/object_info/{node_type}", timeout=10.0)

    info = all_info.get(node_type)
    if not info:
        # Try case-insensitive search
        all_nodes = _get("/object_info", timeout=30.0)
        matches = [n for n in all_nodes if n.lower() == node_type.lower()]
        if matches:
            info = all_nodes[matches[0]]
            node_type = matches[0]
        else:
            # Suggest similar names
            # He2025: sort for deterministic suggestion order
            similar = sorted(n for n in all_nodes if node_type.lower() in n.lower())[:10]
            return to_json({
                "error": f"Node type '{node_type}' not found.",
                "similar_nodes": similar,
            })

    return to_json({
        "class_type": node_type,
        "display_name": info.get("display_name", node_type),
        "category": info.get("category", ""),
        "description": info.get("description", ""),
        "input": info.get("input", {}),
        "output": info.get("output", []),
        "output_name": info.get("output_name", []),
        "output_is_list": info.get("output_is_list", []),
    })


def _handle_get_system_stats() -> str:
    stats = _get("/system_stats", timeout=5.0)
    return to_json(stats)


def _handle_get_queue() -> str:
    queue = _get("/queue", timeout=5.0)
    running = queue.get("queue_running", [])
    pending = queue.get("queue_pending", [])
    return to_json({
        "running_count": len(running),
        "pending_count": len(pending),
        "running": [{"prompt_id": r[1]} for r in running] if running else [],
        "pending": [{"prompt_id": p[1]} for p in pending] if pending else [],
    })


def _handle_get_history(tool_input: dict) -> str:
    prompt_id = tool_input.get("prompt_id")
    max_items = tool_input.get("max_items", 5)

    if prompt_id:
        history = _get(f"/history/{prompt_id}", timeout=10.0)
    else:
        history = _get("/history", timeout=10.0)

    # Trim to max_items
    if not prompt_id and len(history) > max_items:
        # History keys are prompt IDs; take most recent
        keys = list(history.keys())[-max_items:]
        history = {k: history[k] for k in keys}

    # Summarize outputs
    result = {}
    # He2025: sort for deterministic output order
    for pid, entry in sorted(history.items()):
        outputs_summary = []
        for node_id, node_out in sorted(entry.get("outputs", {}).items()):
            for img in node_out.get("images", []):
                outputs_summary.append({
                    "type": "image",
                    "filename": img.get("filename"),
                })
            for vid in node_out.get("gifs", []):
                outputs_summary.append({
                    "type": "video",
                    "filename": vid.get("filename"),
                })
        status_info = entry.get("status", {})
        result[pid] = {
            "status": status_info.get("status_str", "unknown"),
            "completed": status_info.get("completed", False),
            "outputs": outputs_summary,
        }

    return to_json(result)


# ---------------------------------------------------------------------------
# Dispatch
# ---------------------------------------------------------------------------

def handle(name: str, tool_input: dict) -> str:
    """Execute a comfy_api tool call."""
    try:
        if name == "is_comfyui_running":
            return _handle_is_running()
        elif name == "get_all_nodes":
            return _handle_get_all_nodes(tool_input)
        elif name == "get_node_info":
            return _handle_get_node_info(tool_input)
        elif name == "get_system_stats":
            return _handle_get_system_stats()
        elif name == "get_queue_status":
            return _handle_get_queue()
        elif name == "get_history":
            return _handle_get_history(tool_input)
        else:
            return to_json({"error": f"Unknown tool: {name}"})
    except httpx.ConnectError:
        return to_json({
            "error": f"Could not connect to ComfyUI at {COMFYUI_URL}. Is it running?",
        })
    except httpx.HTTPStatusError as e:
        return to_json({
            "error": f"HTTP {e.response.status_code}: {e.response.text[:200]}",
        })
    except Exception as e:
        return to_json({"error": str(e)})

